// Lernliste je Art: Kopie der Grundliste der Linie + vier Attacken des Zweit-Typs (L12/24/34/46). Legenden: Typ-Grundliste + Signatur-Attacke ab L40
const TPL={glut:L_GLUT,flut:L_FLUT,flora:L_FLORA,volt:L_VOLT,fels:L_GRAN,frost:L_FROST,boe:L_BOE,schatten:L_SCHAT,lumen:L_LUMEN,kern:L_NAGE,ursprung:L_URSP};
const T2MV={glut:['funken','glutwirbel','glutwelle','brunst'],flut:['spritzer','blubber','wellen','tiefen'],flora:['ranke','dorn','blattsturm','waldzorn'],volt:['zitter','bogen','donner','gewitter'],
 fels:['stein','erd','lawine','beben'],frost:['eishauch','frostzahn','hagel','nullp'],boe:['wind','fluegel','luft','orkan'],schatten:['kralle','nachtbiss','albtraum','finster'],
 lumen:['lichtpuls','glanz','prisma','krone'],kern:['schnell','wucht','fokus','hyper'],ursprung:['lichtpuls','konzentrat','glanz','prisma']};
function lsOf(base,t2){const L=base.map(e=>e.slice());if(t2&&T2MV[t2]&&!base.some(e=>MOVES[e[1]]&&MOVES[e[1]][1]===t2))[12,24,34,46].forEach((lv,i)=>addLearn(L,lv,T2MV[t2][i]));return L;}
function lsLeg(t,sig){const L=lsOf(TPL[t[0]],t[1]||null).filter(e=>e[0]<40);addLearn(L,40,sig);addLearn(L,55,'konzentrat');addLearn(L,60,T2MV[t[0]][3]);return L;}

